<script>function lorryOrderPos(){return{search:'',cart:[],discountType:'fixed',discountAmount:0,paymentMethod:'',showPayment:false,get subtotal(){return this.cart.reduce((s,i)=>s+i.qty*i.price,0)},get calculatedDiscount(){let value=Math.max(0,Number(this.discountAmount)||0);return this.discountType==='percentage'?this.subtotal*(Math.min(value,100)/100):value},get appliedDiscount(){return Math.min(this.subtotal,this.calculatedDiscount)},get total(){return Math.max(0,this.subtotal-this.appliedDiscount)},matches(t){return !this.search||t.includes(this.search.toLowerCase())},add(p){let i=this.cart.find(x=>x.id===p.id);if(i)this.increase(i);else this.cart.push({id:p.id,name:p.name,price:Number(p.wholesale_price),stock:Number(p.available_quantity),qty:1})},increase(i){if(i.qty<i.stock)i.qty++},decrease(i){if(i.qty>1)i.qty--},clearCart(){this.cart=[];this.discountAmount=0;this.paymentMethod='';this.showPayment=false},money(v){return 'Rs. '+Number(v).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2})},prepareSubmit(e){let cSelect=document.querySelector('select[name="customer_id"]');let cName=cSelect.options[cSelect.selectedIndex]?.text||'';if((this.paymentMethod==='Cheque'||this.paymentMethod==='Multi')&&cName.toLowerCase().includes('walk-in')){if(e)e.preventDefault();Swal.fire({title:'Customer Required',text:'Please select a valid customer (not Walk-in) for this payment method.',icon:'warning',confirmButtonColor:'#f59e0b'});this.showPayment=false;return false;}let box=document.getElementById('order-items');box.innerHTML='';this.cart.forEach((i,n)=>box.insertAdjacentHTML('beforeend',`<input type="hidden" name="items[${n}][product_id]" value="${i.id}"><input type="hidden" name="items[${n}][quantity]" value="${i.qty}">`))}}}</script>
